#include <iostream>
#include <utility>

template<typename R, typename F, typename... BoundArgs>
auto my_bind(F&& f, BoundArgs&&... args) {
    return [f = std::forward<F>(f), ...args = std::forward<BoundArgs>(args)]() {
        return f(std::forward<BoundArgs>(args)...);
    };
}

int add(int a, int b) { return a + b; }

int main() {
    auto bound_func = my_bind<int>(add, 3, 4);
    std::cout << "Result: " << bound_func() << std::endl;
    return 0;
}
